{"version":3,"file":"Lightbox-DvpADwYF.js","sources":["../../../src/components/Lightbox.js"],"sourcesContent":["import { Viewport } from '/utils/less-layout-trashing'\nimport mediaReady from '/utils/media-ready'\nimport IS_MOBILE from '/utils/is-mobile'\n\nexport const selector = '.lightbox'\n\nconst FIGURE_SELECTOR = '.gallery figure'\nconst PLACEHOLDER_TIMING = { duration: 300, easing: 'cubic-bezier(0.25, 0.1, 0.25, 1)' }\n\nexport function hydrate (element) {\n  if (IS_MOBILE) return\n\n  let current\n\n  const reducedMotion = window.matchMedia('(prefers-reduced-motion)').matches\n\n  const placeholder = element.querySelector('.lightbox__placeholder')\n  const slides = Array.from(\n    document.querySelectorAll(FIGURE_SELECTOR)\n  ).map((figure, index) => {\n    // Bind\n    figure.classList.add('has-lightbox')\n    figure.addEventListener('click', async e => {\n      e.preventDefault()\n      figure.classList.add('has-lightbox-loading')\n      await open(index)\n      figure.classList.remove('has-lightbox-loading')\n    })\n\n    const element = figure.querySelector('img, video')\n    return element && { element }\n  }).filter(Boolean)\n\n  element.addEventListener('click', handleClick)\n  window.addEventListener('keydown', handleKey)\n\n  return {\n    destroy: () => {\n      window.removeEventListener('keydown', handleKey)\n    }\n  }\n\n  async function open (index = 0) {\n    cleanup(slides[current])\n    placeholder.classList.remove('is-ready')\n\n    current = index\n    const slide = slides[current]\n    if (!slide) return\n\n    // Create a filler to replace slide media\n    slide.filler = document.createElement('div')\n    slide.filler.classList.add('filler')\n    slide.filler.style.aspectRatio = slide.element.width / slide.element.height\n    slide.element.replaceWith(slide.filler)\n\n    // Insert slide media into the lightbox\n    placeholder.append(slide.element)\n\n    // Transition to fullscreen\n    if (!reducedMotion && !element.classList.contains('is-open')) {\n      // Avoid flash\n      await mediaReady(slide.element)\n      placeholder.classList.add('is-ready')\n\n      // Compute transformation\n      const from = slide.filler.getBoundingClientRect()\n      const to = contain(from, { width: Viewport.$innerWidth, height: Viewport.$innerHeight }, {\n        padding: parseInt(window.getComputedStyle(placeholder).paddingInline)\n      })\n      const scale = from.width / to.width\n\n      // Prepare CSS border-radius animation\n      placeholder.style.setProperty('--scale', scale)\n      void placeholder.offsetWidth // eslint-disable-line no-void\n      placeholder.classList.add('is-animating')\n\n      // Animate transition\n      placeholder.animate([\n        {\n          transform: [\n            `translateX(${from.left - to.left * scale}px)`,\n            `translateY(${from.top - to.top * scale}px)`,\n            `scale(${scale})`\n          ].join(' ')\n        },\n        {\n          transform: 'none'\n        }\n      ], PLACEHOLDER_TIMING)\n    }\n\n    element.classList.add('is-open')\n  }\n\n  function cleanup (slide) {\n    slide?.filler.replaceWith(slide.element)\n  }\n\n  function close () {\n    cleanup(slides[current])\n\n    element.classList.remove('is-open')\n    placeholder.classList.remove('is-ready')\n    placeholder.classList.remove('is-animating')\n  }\n\n  function handleClick (e) {\n    if (e.target.matches('video[controls]')) return\n    close()\n  }\n\n  function handleKey (e) {\n    if (!element.classList.contains('is-open')) return\n\n    if (e.key === 'Escape') close()\n    if (e.key === 'ArrowRight') open((current + 1) % slides.length)\n    if (e.key === 'ArrowLeft') open((current + slides.length - 1) % slides.length)\n  }\n}\n\nfunction contain (source, target, {\n  padding = 0\n} = {}) {\n  const containerWidth = target.width - padding * 2\n  const containerHeight = target.height - padding * 2\n  const ratio = source.width / source.height\n  const targetRatio = containerWidth / containerHeight\n\n  let width, height\n\n  if (ratio > targetRatio) {\n    width = containerWidth\n    height = containerWidth / ratio\n  } else {\n    height = containerHeight\n    width = containerHeight * ratio\n  }\n\n  return {\n    top: (target.height - height) / 2,\n    left: (target.width - width) / 2,\n    width,\n    height\n  }\n}\n"],"names":["selector","FIGURE_SELECTOR","PLACEHOLDER_TIMING","hydrate","element","IS_MOBILE","current","reducedMotion","placeholder","slides","figure","index","e","open","handleClick","handleKey","cleanup","slide","mediaReady","from","to","contain","Viewport","scale","close","source","target","padding","containerWidth","containerHeight","ratio","targetRatio","width","height"],"mappings":"2IAIY,MAACA,EAAW,YAElBC,EAAkB,kBAClBC,EAAqB,CAAE,SAAU,IAAK,OAAQ,kCAAkC,EAE/E,SAASC,EAASC,EAAS,CAChC,GAAIC,EAAW,OAEf,IAAIC,EAEJ,MAAMC,EAAgB,OAAO,WAAW,0BAA0B,EAAE,QAE9DC,EAAcJ,EAAQ,cAAc,wBAAwB,EAC5DK,EAAS,MAAM,KACnB,SAAS,iBAAiBR,CAAe,CAC7C,EAAI,IAAI,CAACS,EAAQC,IAAU,CAEvBD,EAAO,UAAU,IAAI,cAAc,EACnCA,EAAO,iBAAiB,QAAS,MAAME,GAAK,CAC1CA,EAAE,eAAc,EAChBF,EAAO,UAAU,IAAI,sBAAsB,EAC3C,MAAMG,EAAKF,CAAK,EAChBD,EAAO,UAAU,OAAO,sBAAsB,CAChD,CAAC,EAED,MAAMN,EAAUM,EAAO,cAAc,YAAY,EACjD,OAAON,GAAW,CAAE,QAAAA,CAAO,CAC7B,CAAC,EAAE,OAAO,OAAO,EAEjB,OAAAA,EAAQ,iBAAiB,QAASU,CAAW,EAC7C,OAAO,iBAAiB,UAAWC,CAAS,EAErC,CACL,QAAS,IAAM,CACb,OAAO,oBAAoB,UAAWA,CAAS,CACjD,CACJ,EAEE,eAAeF,EAAMF,EAAQ,EAAG,CAC9BK,EAAQP,EAAOH,CAAO,CAAC,EACvBE,EAAY,UAAU,OAAO,UAAU,EAEvCF,EAAUK,EACV,MAAMM,EAAQR,EAAOH,CAAO,EAC5B,GAAKW,EAYL,IATAA,EAAM,OAAS,SAAS,cAAc,KAAK,EAC3CA,EAAM,OAAO,UAAU,IAAI,QAAQ,EACnCA,EAAM,OAAO,MAAM,YAAcA,EAAM,QAAQ,MAAQA,EAAM,QAAQ,OACrEA,EAAM,QAAQ,YAAYA,EAAM,MAAM,EAGtCT,EAAY,OAAOS,EAAM,OAAO,EAG5B,CAACV,GAAiB,CAACH,EAAQ,UAAU,SAAS,SAAS,EAAG,CAE5D,MAAMc,EAAWD,EAAM,OAAO,EAC9BT,EAAY,UAAU,IAAI,UAAU,EAGpC,MAAMW,EAAOF,EAAM,OAAO,sBAAqB,EACzCG,EAAKC,EAAQF,EAAM,CAAE,MAAOG,EAAS,YAAa,OAAQA,EAAS,cAAgB,CACvF,QAAS,SAAS,OAAO,iBAAiBd,CAAW,EAAE,aAAa,CAC5E,CAAO,EACKe,EAAQJ,EAAK,MAAQC,EAAG,